/**
 * Per-target action card with translate/validate buttons and manual input.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖pages🔖actionspage🛠️targetactioncard](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Pages/s/ActionsPage/d/i/TargetActionCard)
 *
 * MUST offer tool invocation and manual result input for translate and validate.
 **/
function TargetActionCard({
  targetId,
  loading,
  runTool,
  runCall,
}: {
  targetId: string;
  loading: string | null;
  runTool: (name: string, args: Record<string, unknown>, label: string) => void;
  runCall: (method: string, params: Record<string, unknown>, label: string) => void;
}) {
  const [manualMode, setManualMode] = useState<null | "translate" | "validate">(null);
  const [manualInput, setManualInput] = useState("");

  const handleManualSubmit = useCallback(() => {
    if (!manualInput.trim() || !manualMode) return;
    try {
      const parsed = JSON.parse(manualInput);
      if (manualMode === "translate") {
        runCall("save_translation", { target_id: targetId, translation: parsed }, `Manual Translate ${targetId}`);
      } else {
        runCall("save_validation", { target_id: targetId, validation: parsed }, `Manual Validate ${targetId}`);
      }
      setManualInput("");
      setManualMode(null);
    } catch {
      // Input is not valid JSON — try as plain text
      if (manualMode === "translate") {
        runCall("save_translation", { target_id: targetId, translation: manualInput.trim() }, `Manual Translate ${targetId}`);
      } else {
        runCall("save_validation", { target_id: targetId, validation: manualInput.trim() }, `Manual Validate ${targetId}`);
      }
      setManualInput("");
      setManualMode(null);
    }
  }, [manualInput, manualMode, targetId, runTool, runCall]);

  return (
    <div className="rounded border border-border p-3 space-y-2">
      <div className="text-sm font-medium text-text font-mono">{targetId}</div>
      <div className="flex gap-2">
        <Button
          onClick={() => runTool("translate", { target_id: targetId }, `Translate ${targetId}`)}
          loading={loading === `Translate ${targetId}`}
          disabled={loading !== null}
        >
          <IconTranslations className="w-3.5 h-3.5" />
          Translate
